// Demo-mode sample photos for the report form.
//
// - Photos: public/demo/samples/<photoId>.jpg, produced by `npm run demo:photos`
//   from files you drop in demo-photos-raw/ (see scripts/demo/prepare-sample-photos.mjs).
// - Analyses: ./demo-sample-analyses.json, keyed by sample id. `source: 'gpt-4o'` entries
//   were generated by `npm run demo:analyze` with the app's own prompt and schema;
//   `source: 'placeholder'` entries are hand-written stand-ins.
//
// Uses relative imports only, so the generator script can load it with tsx.

import type { AIAnalysisResult, IssueCategory } from '@/types';
import { AnalysisSchema } from '../lib/openai/analysis-shared';
import PHOTO_IDS from './demo-photo-ids.json';
import analysesJson from './demo-sample-analyses.json';

export type PhotoId = 'pothole' | 'broken_streetlight' | 'damaged_sidewalk' | 'illegal_dumping' | 'graffiti' | 'flooding';

export interface DemoSample {
  id: string;
  photoId: PhotoId;
  image: string;
  label: string;
  /** What the photo shows (used for the fallback tile if the image fails to load). */
  category: IssueCategory;
  description: string;
  latitude: number;
  longitude: number;
  address: string;
  neighborhood: string;
}

export interface SavedAnalysis {
  analysis: AIAnalysisResult;
  source: 'gpt-4o' | 'placeholder';
  model?: string;
  generatedAt?: string;
}

export const DEMO_PHOTO_IDS = PHOTO_IDS as PhotoId[];

