export const DEMO_SAMPLES: DemoSample[] = SAMPLE_INPUTS.map(s => ({ ...s, image: samplePhotoPath(s.photoId) }));

/** Public path of a sample photo, by photo id. */
export function samplePhotoPath(photoId: PhotoId): string {
  return `/demo/samples/${photoId}.jpg`;
}

// ─── Saved analyses ───────────────────────────────────────────────────────────

const rawAnalyses = analysesJson as Record<string, unknown>;

/** The saved analysis for a sample, validated with the app's schema; null if missing or invalid. */
export function getSavedAnalysis(sampleId: string): SavedAnalysis | null {
  const entry = rawAnalyses[sampleId] as Partial<SavedAnalysis> | undefined;
  if (!entry || (entry.source !== 'gpt-4o' && entry.source !== 'placeholder')) return null;
  const parsed = AnalysisSchema.safeParse(entry.analysis);
  if (!parsed.success) return null;
  return { analysis: parsed.data, source: entry.source, model: entry.model, generatedAt: entry.generatedAt };
}

/** How many samples have real saved GPT-4o results, for honest UI copy. */
export const SAVED_GPT4O_COUNT = DEMO_SAMPLES.filter(s => getSavedAnalysis(s.id)?.source === 'gpt-4o').length;
export const SAMPLE_COUNT = DEMO_SAMPLES.length;
export const SAVED_ANALYSIS_STATUS: 'all' | 'some' | 'none' =
  SAVED_GPT4O_COUNT === SAMPLE_COUNT ? 'all' : SAVED_GPT4O_COUNT > 0 ? 'some' : 'none';

/**
 * Demo copy that stays accurate while some analyses are still placeholders.
 * Computed on the server (root layout) so this module isn't bundled into every page.
 */
export function getDemoAiCopy(): { bannerNote: string; reportTip: string } {
  switch (SAVED_ANALYSIS_STATUS) {
    case 'all':
      return {
        bannerNote: 'AI results on sample photos are saved GPT-4o outputs; everything else is rule-based (no live AI calls)',
        reportTip: 'Pick a sample photo to see its saved GPT-4o analysis (try “Mismatch test”), or upload your own photo for a rule-based analysis.',
      };
    case 'some':
      return {
        bannerNote: `${SAVED_GPT4O_COUNT} of ${SAMPLE_COUNT} sample photos have saved GPT-4o results; everything else is rule-based (no live AI calls)`,
        reportTip: 'Pick a sample photo to see a saved GPT-4o analysis where available (the rest are placeholders), or upload your own photo for a rule-based analysis.',
      };
    default:
      return {
        bannerNote: 'Analysis is rule-based; sample photo results are placeholders (no live AI calls)',
        reportTip: 'Pick a sample photo (its result is a placeholder for now) or upload your own photo for a rule-based analysis, then see the priority scores.',
      };
  }
}
